async function spin({demo=false}={}){if(!visualReady){await bootPromise;if(!visualReady)return}if(busy||activeRound)return;if(!free&&(bet<BET_UNIT||bet>maxBet(balance))){const insufficient=maxBet(balance)<BET_UNIT;effect(45);toast(insufficient?'蘿蔔不足以進行最低下注':'每次下注最多為現有蘿蔔的10%');return}busy=true;$('#spin').dataset.preparing='true';update();let plan;const isFree=free>0;try{await prepareCardAssets();plan=buildRoundPlan(engine,{bet,isFree});await preparePlanAssets(plan);delete $('#spin').dataset.preparing}catch(error){console.error(error);delete $('#spin').dataset.preparing;busy=false;auto=null;update();toast('牌面圖片未載入完成，請重試');return}const record={id:crypto.randomUUID(),startedAt:Date.now(),plan,credited:false,bonusApplied:false,demo};if(!demo){if(isFree){freeStartPending=false;free--}else balance=Math.round((balance-bet)*100)/100;activeRound=record;save()}music.startRound(isFree,{total:plan.total,bet:plan.bet});update();if(isFree)effect(34,{target:$('#freePill')});return runRecord(record)}
$('#spin').onclick=()=>spin();$('#speed').onclick=()=>{speed=(speed+1)%2;update();effect(44,{target:$('#speed')});toast(['正常速度','2× 快速模式'][speed])};
